CREATE TABLE "publication_intent" (
 "id" uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid() NOT NULL, "user_id" uuid NOT NULL, "video_id" uuid NOT NULL, "publishing_account_id" uuid NOT NULL, "platform" text NOT NULL, "mode" text NOT NULL, "title" text NOT NULL, "description" text, "link" text DEFAULT 'https://vk.com/sovara_news' NOT NULL, "create_community_post" boolean DEFAULT false NOT NULL, "scheduled_at" timestamp with time zone, "preview_object_key" text, "preview_content_type" text, "preview_size_bytes" bigint, "preview_state" text, "revision" integer DEFAULT 0 NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
 CONSTRAINT "publication_intent_video_user_fk" FOREIGN KEY ("video_id","user_id") REFERENCES "video"("id","user_id") ON DELETE restrict, CONSTRAINT "publication_intent_account_user_platform_fk" FOREIGN KEY ("publishing_account_id","user_id","platform") REFERENCES "publishing_account"("id","user_id","platform") ON DELETE restrict,
 CONSTRAINT "publication_intent_platform_check" CHECK ("platform" IN ('youtube','vk')), CONSTRAINT "publication_intent_mode_check" CHECK ("mode" IN ('DRAFT','PUBLISH_NOW','SCHEDULED')), CONSTRAINT "publication_intent_title_check" CHECK (length(trim("title")) > 0 AND length("title") <= 100), CONSTRAINT "publication_intent_vk_description_check" CHECK ("platform" <> 'vk' OR "description" IS NULL OR length("description") <= 5000), CONSTRAINT "publication_intent_schedule_check" CHECK (("mode" = 'SCHEDULED' AND "scheduled_at" IS NOT NULL) OR ("mode" <> 'SCHEDULED' AND "scheduled_at" IS NULL)), CONSTRAINT "publication_intent_preview_check" CHECK (("preview_object_key" IS NULL AND "preview_content_type" IS NULL AND "preview_size_bytes" IS NULL AND "preview_state" IS NULL) OR ("preview_object_key" IS NOT NULL AND "preview_content_type" IN ('image/jpeg','image/png','image/webp') AND "preview_size_bytes" > 0 AND "preview_state" IN ('pending','ready'))), CONSTRAINT "publication_intent_revision_check" CHECK ("revision" >= 0)
);
--> statement-breakpoint
CREATE UNIQUE INDEX "publication_intent_video_account_uidx" ON "publication_intent" USING btree ("video_id","publishing_account_id");--> statement-breakpoint
CREATE INDEX "publication_intent_user_updated_idx" ON "publication_intent" USING btree ("user_id","updated_at");
